// Agrège par email : délivré, total ouvertures/clics, dernier envoi, campagne.
const byEmail = new Map();
for (const it of items) {
  const r = it.json || {};
  const email = String(r.email || '').toLowerCase().trim();
  if (!email) continue;
  const cur = byEmail.get(email) || { email, delivered: 'true', opens: 0, clicks: 0, lastSentAt: '', campaignId: '' };
  cur.opens += Number(r.opens || 0);
  cur.clicks += Number(r.clicks || 0);
  const created = String(r.created_at || '');
  if (created > cur.lastSentAt) {
    cur.lastSentAt = created;
    cur.campaignId = String(r.campaign_id || '');
  }
  byEmail.set(email, cur);
}
return [...byEmail.values()].map((v) => ({ json: { ...v, lastSentAt: v.lastSentAt.slice(0, 16).replace('T', ' ') } }));
